<div class="chat-heading"><div><span class="eyebrow"><?= e($conversation['store_name']) ?></span><h2><?= e($conversation['subject']) ?></h2></div><a href="<?= e(url('/minha-conta/mensagens')) ?>">← Conversas</a></div><section class="chat-panel"><div class="chat-messages"><?php foreach($messages as $message):?><article class="chat-message <?= (int)$message['sender_id']===(int)$authUser['id']?'is-mine':'' ?>"><strong><?= e($message['sender_name']) ?></strong><p><?= nl2br(e($message['body'])) ?></p><time><?= date('d/m/Y H:i',strtotime($message['created_at'])) ?></time></article><?php endforeach;?></div><?php if($conversation['status']==='open'):?><form class="chat-compose" method="post" action="<?= e(url('/minha-conta/mensagens/'.$conversation['id'])) ?>"><?= csrf_field() ?><textarea name="body" required maxlength="5000" placeholder="Digite sua mensagem..."></textarea><button class="button button--primary">Enviar</button></form><?php else:?><div class="alert">Esta conversa foi encerrada.</div><?php endif;?></section>
